CREATE OR REPLACE PROCEDURE sp(para_Club_ID integer, para_Club_name text, para_Votes integer, para_Residence text, para_Points integer) LANGUAGE plpgsql AS
$$
DECLARE
    cur REFCURSOR;
    rec RECORD;
    temp_num INTEGER;
    temp_text TEXT;
    row_count INTEGER;
    flag INTEGER;
BEGIN
    temp_num := 0;
    temp_text := '';
    row_count := 0;
    flag := 0;
    IF para_Club_ID < 10 THEN
        UPDATE "club" SET "Club_name" = 'INACTIVE' WHERE "Club_ID" < para_Club_ID;
        flag := 1;
    ELSIF para_Club_ID < 25 THEN
        OPEN cur FOR SELECT "Votes", "Residence" FROM "player" WHERE "Votes" > para_Votes AND "Residence" LIKE para_Residence FOR UPDATE;
        flag := 2;
    ELSIF para_Club_ID < 40 THEN
        OPEN cur FOR SELECT "Points" FROM "match_result" WHERE "Points" BETWEEN para_Points AND para_Points * 2;
        flag := 3;
    ELSE
        OPEN cur FOR SELECT "Club_ID", "Club_name" FROM "club" WHERE "Club_ID" > para_Club_ID / 2;
        flag := 4;
    END IF;
    IF flag = 2 OR flag = 3 OR flag = 4 THEN
        LOOP
            FETCH cur INTO rec;
            EXIT WHEN NOT FOUND;
            row_count := row_count + 1;
            IF flag = 2 THEN
                IF rec."Votes" < 50 THEN
                    UPDATE "player" SET "Residence" = 'COMPLETED' WHERE CURRENT OF cur;
                ELSE
                    temp_num := temp_num + rec."Votes";
                END IF;
            ELSIF flag = 3 THEN
                IF rec."Points" > 100 THEN
                    temp_text := 'OVER_LIMIT';
                ELSIF rec."Points" > 50 THEN
                    temp_text := 'WITHIN_RANGE';
                ELSE
                    temp_text := 'BELOW_MIN';
                END IF;
            ELSIF flag = 4 THEN
                IF rec."Club_ID" % 2 = 0 THEN
                    temp_num := temp_num + 1;
                END IF;
            END IF;
        END LOOP;
        CLOSE cur;
    END IF;
    IF flag = 1 THEN
        DELETE FROM "player" WHERE "Votes" < para_Votes;
    ELSIF flag = 4 AND temp_num > 5 THEN
        UPDATE "club" SET "Club_name" = 'PROCESSED' WHERE "Club_ID" < para_Club_ID;
    ELSE
        UPDATE "player" SET "Residence" = 'DEFAULT' WHERE "Votes" IS NULL;
    END IF;
END;
$$;

